import re

OPT = re.compile(r'^  (?P<opt>--\S+)(?:\s+(?P<rest>\S.*?))?\s*$')

def parse(lines):
    rows = []
    used = []
    skip = []
    cur = None
    started = False
    footer = False
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if footer:
            skip.append(i)
            continue
        m = OPT.match(line)
        if m:
            started = True
            rest = m.group('rest') or ''
            arg = ''
            desc = ''
            if rest:
                parts = re.split(r'\s{2,}', rest, maxsplit=1)
                if len(parts) == 2:
                    arg, desc = parts[0], parts[1]
                elif parts[0][:1] in '<[@':
                    arg = parts[0]
                else:
                    desc = parts[0]
            cur = {'Option': m.group('opt'), 'Argument': arg.strip(), 'Description': desc.strip()}
            rows.append(cur)
            used.append(i)
            continue
        if cur is not None and re.match(r'^ {4,}\S', line):
            t = line.strip()
            cur['Description'] = (cur['Description'] + ' ' + t).strip()
            used.append(i)
            continue
        if started and not line.startswith(' '):
            footer = True
        skip.append(i)
    blocks = []
    if rows:
        blocks.append({'name': 'plugins', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
